mapper.select:
SELECT c.id, c.name, c.type, c.scope, c.threshold, c.amount, c.discount, c.total_count AS totalCount, c.received_count AS receivedCount, (c.total_count - c.received_count) AS remainCount, c.per_limit AS perLimit, c.start_time AS startTime, c.end_time AS endTime, c.status, c.description, c.create_time AS createTime, (SELECT COUNT(*) FROM user_coupon uc WHERE uc.deleted = 0 AND uc.coupon_id = c.id) AS receiveRecordCount, (SELECT COUNT(*) FROM user_coupon uc WHERE uc.deleted = 0 AND uc.coupon_id = c.id AND uc.status = 1) AS usedCount FROM coupon c WHERE c.deleted = 0
AND c.name LIKE CONCAT('%', #{q.name}, '%')
AND c.type = #{q.type}
AND c.scope = #{q.scope}
AND c.status = #{q.status}
AND c.start_time IS NOT NULL AND c.start_time > NOW()
AND (c.start_time IS NULL OR c.start_time <= NOW()) AND (c.end_time IS NULL OR c.end_time > NOW())
AND c.end_time IS NOT NULL AND c.end_time <= NOW()
ORDER BY c.status DESC, c.id DESC
